interface TaskRepository {
    void save(String owner, String title);
    int countByOwner(String owner);
}

class TaskService {
    private final TaskRepository repository;
    private final int taskLimitPerUser = 5;

    TaskService(TaskRepository repository) { this.repository = repository; }

    boolean addTask(String owner, String title) {
        if (repository.countByOwner(owner) >= taskLimitPerUser) return false; // regula TUTAJ
        repository.save(owner, title);
        return true;
    }
}

class TaskController { // czysty tlumacz formatu, zero logiki biznesowej
    private final TaskService service;
    TaskController(TaskService service) { this.service = service; }

    String handleAddTaskRequest(String owner, String title) {
        boolean added = service.addTask(owner, title);
        return added ? "201 Created" : "400 Bad Request: limit zadan przekroczony";
    }
}

class TaskCliCommand { // inny "kontroler" - ta sama zasada
    private final TaskService service;
    TaskCliCommand(TaskService service) { this.service = service; }

    String handleAddTaskCliCommand(String owner, String title) {
        boolean added = service.addTask(owner, title); // TEN SAM Service co REST kontroler
        return added ? "Zadanie dodane" : "Blad: przekroczono limit zadan";
    }
}

